// Story US-014 criterion 3: what Caddy actually runs, asserted on the JSON that Caddy 2.11.9
// adapts infra/caddy/Caddyfile into (infra/caddy/adapted.test.json, regenerated by
// infra/verify/local/caddy-adapt.sh with test values). The behaviour behind these settings is
// exercised end to end by infra/verify/local/stack-sim.sh.
import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import { readQuadlet } from "./quadlet.ts";

const caddyfilePath = new URL("../../caddy/Caddyfile", import.meta.url);
const adapted = JSON.parse(readFileSync(new URL("../../caddy/adapted.test.json", import.meta.url), "utf8")) as {
  caddyfileSha256: string;
  config: CaddyConfig;
};

type Json = Record<string, unknown>;
/** A log field filter: one regexp, or several applied in order (multi_regexp). */
interface LogFilter {
  filter: string;
  regexp?: string;
  value?: string;
  operations?: { regexp: string; value: string }[];
}
interface Route {
  match?: Json[];
  handle?: Handler[];
  terminal?: boolean;
}
interface Handler extends Json {
  handler: string;
  routes?: Route[];
}
interface Server extends Json {
  listen?: string[];
  routes?: Route[];
  strict_sni_host?: boolean;
  protocols?: string[];
}
interface CaddyConfig {
  admin: { disabled?: boolean };
  logging: { logs: Record<string, { encoder?: { format: string; fields: Record<string, LogFilter> } }> };
  apps: {
    http: { servers: Record<string, Server> };
    tls: { automation: { policies: Json[]; on_demand: { permission: { endpoint: string; module: string } } } };
  };
}

const config = adapted.config;
const servers = config.apps.http.servers;
const https = Object.values(servers).find((s) => s.listen?.includes("fd/4"));
const http = Object.values(servers).find((s) => s.listen?.includes("fd/3"));

/** Every handler under a route list, depth first. */
function handlers(routes: Route[] | undefined): Handler[] {
  return (routes ?? []).flatMap((r) => (r.handle ?? []).flatMap((h) => [h, ...handlers(h.routes)]));
}
/** Every route under a route list, depth first. */
function routes(list: Route[] | undefined): Route[] {
  return (list ?? []).flatMap((r) => [r, ...routes((r.handle ?? []).flatMap((h) => h.routes ?? []))]);
}
function site(host: string | null): Route {
  const found = https?.routes?.find((r) =>
    host === null ? r.match === undefined : (r.match?.[0]?.["host"] as string[] | undefined)?.includes(host),
  );
  if (found === undefined) throw new Error(`no site ${host ?? "(catch-all)"}`);
  return found;
}
const reverseProxies = (route: Route) => handlers([route]).filter((h) => h.handler === "reverse_proxy");
const dials = (h: Handler) => (h["upstreams"] as { dial: string }[]).map((u) => u.dial);
const APP_HOSTS = ["admin.example.test", "play.example.test", "order.example.test", "api.example.test"];
/** The name of the access logger Caddy attached to a site (the server's logs.logger_names). */
const loggerOf = (host: string): string => {
  const names = (https?.["logs"] as { logger_names?: Record<string, string[]> } | undefined)?.logger_names?.[host];
  if (names?.length !== 1 || names[0] === undefined) throw new Error(`no access logger for ${host}`);
  return names[0];
};
const orderLogName = (): string => loggerOf("order.example.test");

describe("adapted Caddyfile", () => {
  it("is the adaptation of the current Caddyfile (run infra/verify/local/caddy-adapt.sh after editing it)", () => {
    expect(createHash("sha256").update(readFileSync(caddyfilePath)).digest("hex")).toBe(adapted.caddyfileSha256);
  });

  it("has the admin API off", () => {
    expect(config.admin.disabled).toBe(true);
  });

  it("listens only on the socket-activated descriptors: fd/3 (:80) and fd/4 (:443)", () => {
    const listens = Object.values(servers).flatMap((s) => s.listen ?? []);
    expect(listens.sort()).toEqual(["fd/3", "fd/4"]);
    expect(https?.["listen_protocols"]).toEqual([["h1", "h2"]]);
  });

  it("sets strict_sni_host and h1/h2 on every server and trusts no proxy in front of Caddy", () => {
    for (const server of Object.values(servers)) {
      expect(server.strict_sni_host).toBe(true);
      expect(server.protocols).toEqual(["h1", "h2"]);
      expect(server["trusted_proxies"]).toBeUndefined();
      expect(server["client_ip_headers"]).toBeUndefined();
    }
  });

  it("has host blocks for admin, play, order and api, then the LP catch-all", () => {
    expect(https?.routes?.map((r) => (r.match?.[0]?.["host"] as string[] | undefined)?.[0] ?? null)).toEqual([
      "admin.example.test",
      "order.example.test",
      "play.example.test",
      "api.example.test",
      null,
    ]);
  });

  it("only redirects to HTTPS on port 80", () => {
    expect(handlers(http?.routes).map((h) => [h.handler, h["status_code"]])).toEqual([["static_response", 308]]);
  });

  it("blocks /internal (and the load balancer's /livez) on every host", () => {
    for (const host of [...APP_HOSTS, null]) {
      const blocked = routes([site(host)]).find((r) => (r.match?.[0]?.["path"] as string[] | undefined)?.includes("/internal/*"));
      expect(blocked?.match?.[0]?.["path"], String(host)).toEqual(["/internal", "/internal/*", "/livez", "/livez/*"]);
      expect(handlers(blocked?.handle?.flatMap((h) => h.routes ?? [])).map((h) => h["status_code"])).toEqual([404]);
    }
  });

  it("gets certificates by TLS-ALPN only, and LP certificates only when internal:9000 approves the host", () => {
    const tls = config.apps.tls.automation;
    expect(tls.on_demand.permission).toEqual({ endpoint: "http://internal:9000/caddy/ask", module: "http" });
    const onDemand = tls.policies.filter((p) => p["on_demand"] === true);
    expect(onDemand).toHaveLength(1);
    for (const policy of tls.policies) {
      expect((policy["issuers"] as Json[])[0]?.["challenges"]).toMatchObject({ http: { disabled: true } });
    }
    expect(handlers([site(null)]).find((h) => h.handler === "file_server")).toBeDefined();
  });

  it("serves LP hosts from the symlink-swapped root, GET/HEAD and lowercase hosts only", () => {
    const lp = routes([site(null)]).find((r) => r.match?.[0]?.["expression"] !== undefined);
    expect(lp?.match?.[0]?.["method"]).toEqual(["GET", "HEAD"]);
    expect((lp?.match?.[0]?.["expression"] as { expr: string } | undefined)?.expr).toContain('{http.request.host}.matches("^[a-z0-9]');
    expect(handlers([site(null)]).find((h) => h.handler === "vars")?.["root"]).toBe("/srv/lp/hosts/{http.request.host}/current");
    // Caddy adds its own config file to `hide`.
    expect(handlers([site(null)]).find((h) => h.handler === "file_server")?.["hide"]).toEqual([".*", "/etc/caddy/Caddyfile"]);
  });

  // US-019: the landing-page SDK, static files from /srv/sdk (infra/verify/local/sdk-headers.sh runs
  // the same block in a real Caddy and checks the headers a browser receives).
  describe("SDK route of api.<DOMAIN>", () => {
    const sdk = routes([site("api.example.test")]).find((r) => (r.match?.[0]?.["path"] as string[] | undefined)?.includes("/sdk/*"));
    const inner = (sdk?.handle ?? []).flatMap((h) => h.routes ?? []);
    /** The routes of the SDK block that set a Cache-Control header, with the value they set. */
    const cacheRoutes = inner.flatMap((r) =>
      handlers([r])
        .filter((h) => h.handler === "headers")
        .map((h) => ({ value: ((h["response"] as { set?: Record<string, string[]> }).set ?? {})["Cache-Control"]?.[0], match: r.match?.[0] }))
        .filter((c) => c.value !== undefined),
    );

    it("strips /sdk and serves /srv/sdk through file_server, compressed, hiding dot files", () => {
      expect(sdk).toBeDefined();
      expect(handlers(inner).find((h) => h.handler === "rewrite")?.["strip_path_prefix"]).toBe("/sdk");
      expect(handlers(inner).find((h) => h.handler === "vars")?.["root"]).toBe("/srv/sdk");
      expect(handlers(inner).find((h) => h.handler === "encode")?.["prefer"]).toEqual(["zstd", "gzip"]);
      expect((handlers(inner).find((h) => h.handler === "file_server")?.["hide"] as string[]).includes(".*")).toBe(true);
    });

    it("lets a page on another origin read the files: CORS for the Cap widget's fetch of its WebAssembly, CORP for COEP pages", () => {
      const sets = handlers(inner)
        .filter((h) => h.handler === "headers")
        .map((h) => (h["response"] as { set?: Record<string, string[]> }).set ?? {});
      const unconditional = inner.filter((r) => r.match === undefined).flatMap((r) => handlers([r]).filter((h) => h.handler === "headers"));
      expect(unconditional).toHaveLength(1);
      expect((unconditional[0]?.["response"] as { set: Record<string, string[]> }).set).toEqual({ "Access-Control-Allow-Origin": ["*"], "Cross-Origin-Resource-Policy": ["cross-origin"] });
      expect(sets.length).toBe(3);
    });

    it("caches a versioned file for a year as immutable and the alias for 5 minutes, and nothing else", () => {
      expect(cacheRoutes.map((c) => c.value)).toEqual(["public, max-age=31536000, immutable", "public, max-age=300"]);
      const [immutable, alias] = cacheRoutes;
      // Only for a file that exists: a 404 for a version that is not deployed yet is never cached.
      expect(immutable?.match?.["file"]).toEqual({ try_files: ["{http.request.uri.path}"] });
      expect(alias?.match?.["file"]).toEqual({ try_files: ["{http.request.uri.path}"] });
      expect(alias?.match?.["path"]).toEqual(["/v1.js"]);
    });

    it("treats exactly sdk-v<semver>.js, cap-v<semver>.js and the two versioned Cap wasm files as immutable", () => {
      const pattern = new RegExp(((cacheRoutes[0]?.match?.["path_regexp"] as { pattern: string }).pattern));
      for (const name of ["/sdk-v1.0.0.js", "/sdk-v1.12.345.js", "/cap-v0.1.62.js", "/cap-wasm-v0.0.8.wasm", "/cap-hashwx-v0.0.8.wasm"]) expect(pattern.test(name), name).toBe(true);
      for (const name of ["/v1.js", "/sdk-v1.js", "/sdk-v1.0.0.js.map", "/sdk-v1.0.0.json", "/x/sdk-v1.0.0.js", "/sdk-v1.0.0.js/x", "/SDK-V1.0.0.JS", "/sdk-v1.0.0-beta.js", "/sdk-v1.0.0.js\n", "/cap-wasm.wasm", "/cap-wasm-v0.0.8.js", "/cap-other-v0.0.8.wasm", "/cap-wasm-v0.0.8.wasm.br", "/x/cap-wasm-v0.0.8.wasm"]) {
        expect(pattern.test(name), name).toBe(false);
      }
    });

    it("comes before the proxy to the public app, so the app never sees /sdk/", () => {
      const apiRoutes = (site("api.example.test").handle ?? []).flatMap((h) => h.routes ?? []);
      const group = apiRoutes.filter((r) => (r as Json)["group"] !== undefined);
      const position = (test: (r: Route) => boolean): number => group.findIndex(test);
      const sdkAt = position((r) => (r.match?.[0]?.["path"] as string[] | undefined)?.includes("/sdk/*") === true);
      const proxyAt = position((r) => r.match === undefined && reverseProxies(r).some((h) => dials(h).includes("public-a:3000")));
      expect(sdkAt).toBeGreaterThanOrEqual(0);
      expect(proxyAt).toBeGreaterThan(sdkAt);
    });
  });

  it("load-balances public@a/b with an active /livez health check", () => {
    for (const host of ["play.example.test", "order.example.test", "api.example.test"]) {
      const lb = reverseProxies(site(host)).find((h) => dials(h).includes("public-a:3000"));
      expect(lb && dials(lb), host).toEqual(["public-a:3000", "public-b:3000"]);
      expect(lb?.["health_checks"]).toEqual({
        active: { expect_status: 200, fails: 1, interval: 2_000_000_000, passes: 2, timeout: 1_000_000_000, uri: "/livez" },
        passive: { fail_duration: 10_000_000_000 },
      });
      expect(lb?.["load_balancing"]).toMatchObject({ try_duration: 10_000_000_000, try_interval: 250_000_000 });
    }
    expect(reverseProxies(site("admin.example.test")).map(dials)).toEqual([["admin:3000"]]);
  });

  it("closes idle app connections (30 s) before the apps do (65 s, packages/edge KEEP_ALIVE_TIMEOUT_MS)", () => {
    const appProxies = APP_HOSTS.flatMap((host) => reverseProxies(site(host))).filter((h) => !dials(h).includes("internal:9000"));
    expect(appProxies.length).toBeGreaterThanOrEqual(4);
    for (const proxy of appProxies) {
      expect(proxy["transport"]).toEqual({ keep_alive: { idle_timeout: 30_000_000_000 }, protocol: "http" });
    }
  });

  it("sends exactly the TCP peer as X-Forwarded-For and strips other client-address headers", () => {
    const all = APP_HOSTS.flatMap((host) => reverseProxies(site(host)));
    expect(all.length).toBeGreaterThanOrEqual(5);
    for (const proxy of all) {
      const headers = (proxy["headers"] as { request: { set: Json; delete: string[] } }).request;
      expect(headers.set).toEqual({ "X-Forwarded-For": ["{http.request.remote.host}"] });
      expect(headers.delete).toEqual(
        expect.arrayContaining(["X-Real-IP", "Forwarded", "X-Client-IP", "True-Client-IP", "CF-Connecting-IP"]),
      );
    }
  });

  it("routes only POST /hooks/glitchtip/<token> from the GlitchTip host to internal, 64 KB max", () => {
    const hook = routes([site("api.example.test")]).find((r) => JSON.stringify(r.match ?? []).includes("path_regexp"));
    expect(hook?.match).toEqual([
      {
        method: ["POST"],
        path_regexp: { name: "glitchtip", pattern: "^/hooks/glitchtip/[A-Za-z0-9_-]{16,512}$" },
        remote_ip: { ranges: ["198.51.100.20/32"] },
      },
    ]);
    const inner = handlers([hook ?? {}]);
    expect(inner.find((h) => h.handler === "request_body")?.["max_size"]).toBe(64_000);
    expect(inner.filter((h) => h.handler === "reverse_proxy").map(dials)).toEqual([["internal:9000"]]);
    expect(reverseProxies(site("api.example.test")).flatMap(dials).filter((d) => d.startsWith("internal"))).toEqual(["internal:9000"]);
    for (const host of ["admin.example.test", "play.example.test", "order.example.test"]) {
      expect(reverseProxies(site(host)).flatMap(dials).some((d) => d.startsWith("internal")), host).toBe(false);
    }
  });

  it("routes only POST /api/v1/webhooks/waha from the WAHA hosts (WAHA_ALLOWED_CIDRS) to the public app, 64 KB max; anyone else gets a 404", () => {
    const outer = routes([site("api.example.test")]).find((r) => JSON.stringify(r.match ?? []).includes("/api/v1/webhooks/waha"));
    expect(outer?.match).toEqual([{ path: ["/api/v1/webhooks/waha"] }]);
    const inner = routes(outer?.handle?.flatMap((h) => h.routes ?? []));
    const allowed = inner.find((r) => JSON.stringify(r.match ?? []).includes("remote_ip"));
    expect(allowed?.match).toEqual([{ method: ["POST"], remote_ip: { ranges: ["198.51.100.30/32"] } }]);
    const served = handlers([allowed ?? {}]);
    expect(served.find((h) => h.handler === "request_body")?.["max_size"]).toBe(64_000);
    expect(served.filter((h) => h.handler === "reverse_proxy").flatMap(dials)).toEqual(["public-a:3000", "public-b:3000"]);
    // Everything else under that path: a 404, no upstream at all.
    const refused = inner.find((r) => r.handle?.some((h) => h.handler === "static_response") === true);
    expect(refused?.match).toBeUndefined();
    expect(handlers([refused ?? {}]).map((h) => h["status_code"])).toEqual([404]);
    expect(handlers([refused ?? {}]).some((h) => h.handler === "reverse_proxy")).toBe(false);
    // The allowlist is its own address list, not the GlitchTip host's (WAHA may live elsewhere).
    expect(JSON.stringify(allowed?.match)).not.toContain("198.51.100.20");
  });

  it("answers 404 to admin requests from outside ADMIN_ALLOWED_CIDRS", () => {
    const outside = routes([site("admin.example.test")]).find((r) => JSON.stringify(r.match ?? []).includes('"not"'));
    expect(outside?.match).toEqual([{ not: [{ remote_ip: { ranges: ["192.0.2.0/24", "2001:db8::/32"] } }] }]);
    expect(handlers(outside?.handle?.flatMap((h) => h.routes ?? [])).map((h) => h["status_code"])).toEqual([404]);
  });

  it("keeps cookies off order.<domain> in both directions", () => {
    const headerOps = handlers([site("order.example.test")]).filter((h) => h.handler === "headers");
    expect(headerOps).toContainEqual({ handler: "headers", request: { delete: ["Cookie"] } });
    // ... and none of the headers Next 16 reports a proxy rewrite in: x-middleware-rewrite carries /order/{publicId}.
    expect(headerOps).toContainEqual({
      handler: "headers",
      response: { deferred: true, delete: ["Set-Cookie", "X-Middleware-Rewrite", "X-Nextjs-Rewritten-Path", "X-Nextjs-Rewritten-Query"] },
    });
  });

  it("emits exactly ONE Referrer-Policy per app site: strict-origin on order.<domain> (AC-T5), strict-origin-when-cross-origin elsewhere", () => {
    // Every header operation that sets or adds the field, in any handler of the site: a second one (a
    // later block that was meant to override the first) did not take effect in Caddy 2.11.9.
    const policies = (host: string) =>
      handlers([site(host)])
        .filter((h) => h.handler === "headers")
        .flatMap((h) => {
          const response = h["response"] as Json | undefined;
          return [(response?.["set"] as Json | undefined)?.["Referrer-Policy"], (response?.["add"] as Json | undefined)?.["Referrer-Policy"]].filter((value) => value !== undefined);
        });
    expect(policies("order.example.test")).toEqual([["strict-origin"]]);
    for (const host of ["admin.example.test", "play.example.test", "api.example.test"]) expect(policies(host), host).toEqual([["strict-origin-when-cross-origin"]]);
  });

  it("sets HSTS, nosniff and frame-ancestors 'none' on the app hosts, frame-ancestors 'self' on LP hosts", () => {
    for (const host of APP_HOSTS) {
      const response = handlers([site(host)]).find((h) => h.handler === "headers" && h["response"] !== undefined)?.["response"] as Json;
      expect(response, host).toMatchObject({
        deferred: true,
        add: { "Content-Security-Policy": ["frame-ancestors 'none'"] },
        set: { "Strict-Transport-Security": ["max-age=31536000; includeSubDomains"], "X-Content-Type-Options": ["nosniff"] },
      });
    }
    const lp = handlers([site(null)]).find((h) => h.handler === "headers")?.["response"] as Json;
    expect(lp).toMatchObject({ set: { "Content-Security-Policy": ["frame-ancestors 'self'; base-uri 'self'; object-src 'none'"] } });
  });

  it("redacts the GlitchTip token and every /files URI, query included, from every log", () => {
    const logs = Object.entries(config.logging.logs);
    expect(logs.length).toBe(Object.values(servers).flatMap((s) => s.listen ?? []).length + 5);
    const secretsOp = { regexp: "(?i)^/+(hooks/glitchtip|files)/.*$", value: "/$1/[redacted]" };
    const orderLog = orderLogName();
    for (const [name, log] of logs) {
      expect(log.encoder?.format, name).toBe("filter");
      const uri = log.encoder?.fields["request>uri"];
      // The order origin's log applies the same operation first, then its own (next test).
      if (name === orderLog) expect(uri?.operations?.[0], name).toEqual(secretsOp);
      else expect(uri, name).toEqual({ filter: "regexp", ...secretsOp });
    }
    // The same pattern in JS (RE2 and JS agree on it): the token and the signed URL's query go.
    const redact = (uri: string) => uri.replace(/^\/+(hooks\/glitchtip|files)\/.*$/i, "/$1/[redacted]");
    expect(redact(`/hooks/glitchtip/${"a1".repeat(32)}`)).toBe("/hooks/glitchtip/[redacted]");
    expect(redact("//HOOKS/glitchtip/abc?x=1")).toBe("/HOOKS/glitchtip/[redacted]");
    expect(redact("/files/d/tok3n/x.pdf?sig=s1gn4ture&exp=1")).toBe("/files/[redacted]");
    expect(redact("/checkout/lp_abc?utm=1")).toBe("/checkout/lp_abc?utm=1");
  });

  it("keeps the order's public id and the Referer out of the order origin's access log, and logs every other site with its plain log (US-022)", () => {
    const log = config.logging.logs[orderLogName()];
    const fields = log?.encoder?.fields ?? {};
    expect(Object.keys(fields).sort()).toEqual([
      "request>headers>Authorization",
      "request>headers>Cookie",
      "request>headers>Referer",
      "request>uri",
      "resp_headers>Location",
      "resp_headers>X-Middleware-Rewrite",
      "resp_headers>X-Nextjs-Rewritten-Path",
      "resp_headers>X-Nextjs-Rewritten-Query",
    ]);
    // Location too: an RSC request Next redirects to /order/{publicId}?_rsc=... puts the id there.
    for (const field of ["request>headers>Referer", "resp_headers>X-Middleware-Rewrite", "resp_headers>X-Nextjs-Rewritten-Path", "resp_headers>X-Nextjs-Rewritten-Query", "resp_headers>Location"]) {
      expect(fields[field], field).toEqual({ filter: "delete" });
    }
    const operations = fields["request>uri"]?.operations ?? [];
    expect(fields["request>uri"]?.filter).toBe("multi_regexp");
    // The same operations in JS (RE2 and JS agree on these patterns), applied in order as Caddy does.
    const redact = (uri: string) =>
      operations.reduce((out, op) => out.replace(new RegExp(op.regexp.replace(/^\(\?i\)/, ""), op.regexp.startsWith("(?i)") ? "gi" : "g"), op.value), uri);
    const id = "AbCdEfGhIjKlMnOpQrStUv";
    expect(redact(`/${id}`)).toBe("/[order]");
    // The app's own spelling of the route, as it appears in x-middleware-rewrite and in an internal request.
    expect(redact(`/order/${id}`)).toBe("/[order]");
    expect(redact(`/order/${id}?x=1`)).toBe("/[order]");
    expect(redact("/order")).toBe("/order");
    expect(redact("/order/x")).toBe("/order/x");
    expect(redact(`/${id}?order_id=${id}-1&status_code=200&transaction_status=settlement`)).toBe("/[order]");
    expect(redact(`/?order_id=${id}-2&status_code=407&transaction_status=expire`)).toBe("/?order_id=[redacted]&status_code=407&transaction_status=expire");
    expect(redact(`/?order_id=${id}-2`)).toBe("/?order_id=[redacted]");
    expect(redact("/api/v1/order/status")).toBe("/api/v1/order/status");
    expect(redact("/_next/static/chunks/app.js")).toBe("/_next/static/chunks/app.js");
    expect(redact("/assets/status-paid/status-paid@1x.webp")).toBe("/assets/status-paid/status-paid@1x.webp");
    for (const host of ["admin.example.test", "play.example.test", "api.example.test"]) {
      expect(Object.keys(config.logging.logs[loggerOf(host)]?.encoder?.fields ?? {}).sort(), host).toEqual(["request>headers>Authorization", "request>headers>Cookie", "request>uri"]);
    }
  });

  it("bounds slow clients: 10 s for headers, 30 s for a body, 10 min to write a response (a 100 MB PDF on a slow link)", () => {
    for (const server of Object.values(servers)) {
      expect(server).toMatchObject({ read_header_timeout: 10_000_000_000, read_timeout: 30_000_000_000, write_timeout: 600_000_000_000, idle_timeout: 120_000_000_000 });
    }
  });

  it("retries a failed dial to admin for up to 10 s, like the public load balancer", () => {
    const [admin] = reverseProxies(site("admin.example.test"));
    expect(admin?.["load_balancing"]).toMatchObject({ try_duration: 10_000_000_000 });
  });

  it("is each app's trusted proxy: Caddy's pinned address on the app's network is its TRUSTED_PROXY_IP", () => {
    const caddy: Record<string, string> = Object.fromEntries(
      readQuadlet("caddy.container")
        .get("Container", "Network")
        .map((n) => n.split(":ip=") as [string, string]),
    );
    expect(caddy).toEqual({ "ebt-edge.network": "10.89.50.2", "ebt-admin.network": "10.89.52.2", "ebt-internal.network": "10.89.53.2" });
    expect(readQuadlet("public@.container").environment()["TRUSTED_PROXY_IP"]).toBe(caddy["ebt-edge.network"]);
    expect(readQuadlet("admin.container").environment()["TRUSTED_PROXY_IP"]).toBe(caddy["ebt-admin.network"]);
  });
});
